mapper.insert:
INSERT INTO user_multi_source_data (
    user_id, source_type, data_json, data_version, fetch_status,
    fetched_at, create_time, update_time
) VALUES (
    #{userId}, #{sourceType}, #{dataJson}, #{dataVersion}, #{fetchStatus},
    #{fetchedAt}, #{createTime}, #{updateTime}
)

mapper.select:
SELECT COUNT(DISTINCT user_id)
FROM user_multi_source_data
WHERE source_type = 'device'
  AND user_id <> #{userId}
  AND JSON_UNQUOTE(JSON_EXTRACT(data_json, '$.device_fingerprint_hash')) = #{fingerprint}
